from __future__ import annotations

import math
import numpy as np


def discounted_return(rewards: list[float], gamma: float) -> float:
    values = np.asarray(rewards, dtype=np.float64)
    if values.ndim != 1 or values.size == 0:
        raise ValueError("rewards must be a non-empty 1D sequence")
    if not np.isfinite(values).all():
        raise ValueError("rewards must be finite")
    if not math.isfinite(gamma) or not 0.0 <= gamma <= 1.0:
        raise ValueError("gamma must lie in [0, 1]")

    result = 0.0
    for reward in values[::-1]:
        result = float(reward) + gamma * result
    return float(result)
```

The backward recurrence avoids explicitly computing powers and makes one pass: $O(T)$ time and $O(1)$ additional memory.

