import math
import numpy as np


def softmax_with_temperature(
    logits: np.ndarray,
    temperature: float,
) -> np.ndarray:
    z = np.asarray(logits, dtype=np.float64)
    if z.ndim != 1 or z.size == 0:
        raise ValueError("logits must be a non-empty 1D array")
    if not np.isfinite(z).all():
        raise ValueError("logits must be finite")
    if not math.isfinite(temperature) or temperature <= 0.0:
        raise ValueError("temperature must be finite and positive")

    scaled = z / temperature
    scaled -= scaled.max()
    weights = np.exp(scaled)
    return weights / weights.sum()
```

Subtracting the maximum uses softmax shift invariance and prevents overflow. The common multiplicative factor cancels between numerator and denominator, so probabilities are unchanged.

```python
import math
import numpy as np

def softmax_with_temperature(logits: np.ndarray, temperature: float) -> np.ndarray:
    z = np.asarray(logits, dtype=np.float64)
    if z.ndim != 1 or z.size == 0 or not np.isfinite(z).all():
        raise ValueError("logits must be a non-empty finite 1D array")
    if not math.isfinite(temperature) or temperature <= 0.0:
        raise ValueError("temperature must be finite and positive")
    scaled = z / temperature
    shifted = scaled - np.max(scaled)
    weights = np.exp(shifted)
    return weights / weights.sum()


def categorical_entropy(probabilities: np.ndarray) -> float:
    p = np.asarray(probabilities, dtype=np.float64)
    if p.ndim != 1 or p.size == 0 or not np.isfinite(p).all():
        raise ValueError("probabilities must be a non-empty finite 1D array")
    if np.any(p < 0.0):
        raise ValueError("probabilities must be non-negative")
    if not math.isclose(float(p.sum()), 1.0, rel_tol=1e-10, abs_tol=1e-12):
        raise ValueError("probabilities must sum to 1")

    positive = p > 0.0
    return float(-np.sum(p[positive] * np.log(p[positive])))


def policy_entropy(logits: np.ndarray, temperature: float) -> float:
    return categorical_entropy(softmax_with_temperature(logits, temperature))
```

